public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int toRemove = (int) (0.05 * n);
    int sum = 0;

    for (int i = toRemove; i < n - toRemove; i++) {
        sum += arr[i];
    }

    return (double) sum / (n - 2 * toRemove);
}

