public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    java.util.HashSet<String> uniqueSubstrings = new java.util.HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        uniqueSubstrings.add(s.substring(i, i + k));
    }

    return uniqueSubstrings.size() == Math.pow(2, k);
}

