public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }
    java.util.Set<String> set = new java.util.HashSet<>();
    int count = 0;
    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        if (set.contains(sub)) {
            continue;
        }
        set.add(sub);
        count++;
        if (count == (1 << k)) {
            return true;
        }
    }
    return false;
}

