    int open = 0;
    int close = 0;
    int operations = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            open++;
        } else if (c == ')') {
            if (open > 0) {
                open--;
            } else {
                operations++;
                close++;
            }
        }
    }

    operations += open * 2;
    if (close % 2 != 0) {
        operations += 2;
    }

    return operations;
}

