public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean isNegative = n < 0;
    n = Math.abs(n);
    StringBuilder result = new StringBuilder();
    int count = 0;
    while (n > 0) {
        result.insert(0, n % 10);
        count++;
        if (count % 3 == 0 && n >= 10) {
            result.insert(0, ".");
        }
        n /= 10;
    }
    if (isNegative) {
        result.insert(0, "-");
    }
    return result.toString();
}

